CAPSTONES={
"shared":{"title":"Explain-It-Back Mini Model Lab","goal":"Build and explain a tiny transformer end to end so every later track rests on real understanding.",
 "architecture":"Character- or BPE-level GPT (nanoGPT-scale) trained on a small corpus; notebook plus a short written explainer with diagrams.",
 "infra":"One consumer GPU or a free cloud notebook; data and checkpoints in a versioned folder.",
 "deploy":"Serve the model behind a tiny HTTP endpoint with streaming.",
 "security":"Add an input-length cap and a prompt-injection test showing why system prompts are not security boundaries.",
 "observability":"Log loss curves, tokens/s and memory; plot attention maps for a few prompts.",
 "scaling":"Estimate parameters, FLOPs and KV memory for 10x and 100x versions with the formulas from the concept cards.",
 "cost":"Compute training cost in GPU-hours and $/1M tokens for serving it.",
 "deliverables":["Repo with training + serving code","Explainer post with 3 diagrams","Eval of 20 prompts with notes"]},
"architect":{"title":"Client-Ready AI Reference Architecture","goal":"Design, justify and document a production AI system for a realistic client brief (e.g. regulated insurer claims assistant).",
 "architecture":"Gateway, RAG with ACL-aware retrieval, agent workers with approval queues, eval service, control plane for prompts/policies; multi-region.",
 "infra":"Managed APIs plus one self-hosted open-weight model for sensitive data; landing zone with private networking.",
 "deploy":"Blue/green for app, canary for prompts and models via gateway aliases; IaC for everything.",
 "security":"Threat model (STRIDE + OWASP LLM + lethal trifecta), per-user scoped tools, egress allowlists, audit logs, DPIA.",
 "observability":"Traces with tokens/cost per span, quality sampling, drift alerts, executive dashboard.",
 "scaling":"Tenancy model, quotas, DR plan with RPO/RTO for model, index and prompts.",
 "cost":"Unit economics per claim handled; build-vs-buy comparison at 3 volume levels.",
 "deliverables":["Architecture decision records","C4 diagrams","Threat model","Cost model spreadsheet","Client presentation deck"]},
"engineer":{"title":"Production RAG + Agent Product","goal":"Ship a cited Q&A and task assistant over a real document set, with evals gating every change.",
 "architecture":"Hybrid retrieval (BM25 + HNSW) with reranking, structured tool calls, small agent loop with budgets, semantic cache.",
 "infra":"Containerized app, vector store, gateway client; one environment per stage.",
 "deploy":"CI runs golden + adversarial evals; prompt changes behind flags; one-click rollback.",
 "security":"Doc-borne injection tests, per-user authorization on tools, PII redaction, spend caps.",
 "observability":"OpenTelemetry traces, retrieved-chunk logging, quality dashboards sliced by cohort.",
 "scaling":"Load test to target RPS; queue + backpressure for slow tools.",
 "cost":"Cost per successful answer; routing small vs large model with measured quality delta.",
 "deliverables":["Repo + README","Eval report","Load test results","Incident runbook"]},
"inference":{"title":"SLO-Driven LLM Serving Stack","goal":"Serve an open-weight model at a stated latency SLO with the best $/1M tokens you can prove.",
 "architecture":"vLLM or SGLang with continuous batching, prefix caching, FP8 or INT4, optional speculative decoding; prefix-aware gateway routing; optional P/D disaggregation.",
 "infra":"Kubernetes GPU pool, warm pool, local NVMe weight cache.",
 "deploy":"Rolling engine upgrades with canary and automatic rollback on TTFT/TBT regression.",
 "security":"Authenticated gateway, per-tenant rate limits, isolated adapters, no prompt logging by default.",
 "observability":"TTFT/TBT/goodput percentiles, KV usage, queue depth, acceptance rate, cold-start phases.",
 "scaling":"Autoscale on queue depth; measured cold start; load shedding and fallback model.",
 "cost":"$/1M input and output tokens at 3 utilization levels vs two API prices.",
 "deliverables":["Benchmark report with methodology","Grafana dashboard","Capacity plan","Cold-start breakdown"]},
"infra":{"title":"Multi-Tenant GPU Platform","goal":"Run a shared GPU platform that teams can self-serve safely, with failures handled automatically.",
 "architecture":"GPU Operator, MIG + time-slicing pools, DRA where available, Kueue queues per team, KubeRay/JobSet for training, inference namespace with gateway.",
 "infra":"Two node pools (training with RDMA, inference), parallel FS or object + NVMe cache, NCCL-validated fabric.",
 "deploy":"GitOps for cluster config; driver upgrades with drains; golden images pinned by digest.",
 "security":"Namespaces + network policies, gVisor for untrusted code, signed images and safetensors-only, weight bucket isolation, MCP gateway.",
 "observability":"DCGM + engine metrics, Xid watcher, NCCL test cron, cost per team.",
 "scaling":"Quota borrowing, preemption tiers, spare-node pool, capacity forecast.",
 "cost":"Showback per team in $/GPU-hour and $/1M tokens; idle reclaim savings; power per rack.",
 "deliverables":["Cluster repo (GitOps)","Failure-remediation controller","Runbooks for Xid 48/79/94-95 and NCCL hangs","Monthly FinOps report"]},
"agentic":{"title":"Governed Autonomous Agent","goal":"Build an agent that completes multi-step real tasks safely, measurably and recoverably.",
 "architecture":"Harness with middleware (policy, redaction, approvals), MCP tools via gateway, episodic memory, checkpoint/resume, optional A2A delegation.",
 "infra":"Sandboxed microVM or gVisor runtime, ephemeral FS, egress allowlist, secrets vault.",
 "deploy":"Autonomy level per action class; staged rollout from draft-only to scoped auto.",
 "security":"Lethal-trifecta review, injection red-team suite in CI, pinned MCP manifests, kill switch drill.",
 "observability":"Full trajectory traces, cost per task, policy violations, abstention rate.",
 "scaling":"Concurrency limits, per-task budgets, queue-based workers.",
 "cost":"Cost per successful task vs human baseline.",
 "deliverables":["Agent repo","Eval harness with 50+ tasks run 5x each","Red-team report","Autonomy policy doc"]},
}

