GLOSSARY=[
("A2A","Agent-to-agent protocol for discovering remote agents and delegating tasks with a lifecycle."),
("Agent Card","JSON document advertising an A2A agent's skills, endpoint and auth."),
("All-reduce","Collective where every GPU ends with the sum of all GPUs' buffers."),
("All-to-all","Collective where every GPU sends distinct data to every other GPU; used by MoE expert parallelism."),
("ANN","Approximate nearest neighbor search: fast vector search trading a little recall for speed."),
("AWQ","Activation-aware weight quantization method for INT4 weights."),
("Best-of-N","Sample N answers and pick the best with a scorer or verifier."),
("BPE","Byte-pair encoding tokenizer that merges frequent byte pairs into tokens."),
("busbw","nccl-tests bus bandwidth: algorithm bandwidth normalized to compare with link speed."),
("Capacity factor","MoE setting for how many tokens each expert accepts relative to perfect balance."),
("Chain-of-thought","Prompting or training a model to reason step by step before answering."),
("Chunked prefill","Splitting long prompt processing into chunks interleaved with decode steps."),
("Cold start","Time for a new replica to become ready: node, image, weights, engine init."),
("Confidential computing","Hardware TEEs that encrypt data in use and attest the environment."),
("Confused deputy","A privileged component tricked into misusing its authority for an attacker."),
("Context engineering","Choosing and ordering what goes into a model's context window."),
("Continuous batching","Adding and removing sequences from a batch every decode step."),
("Cross-encoder","Model scoring a query-document pair jointly; accurate, used for reranking."),
("CUDA graphs","Captured sequences of GPU kernels replayed with low CPU launch overhead."),
("DCGM","NVIDIA Data Center GPU Manager: metrics, health checks and diagnostics."),
("Decode","Generation phase producing one token per step; memory-bandwidth-bound."),
("Distillation","Training a smaller student model to imitate a larger teacher."),
("DPO","Direct Preference Optimization: learns from chosen/rejected pairs without RL."),
("DRA","Kubernetes Dynamic Resource Allocation: attribute-based device requests via ResourceClaims."),
("ECC","Error-correcting code memory; GPUs report single- and double-bit errors."),
("Egress allowlist","Network policy permitting outbound traffic only to approved destinations."),
("Embedding","Vector representation of text or other data where similar items are close."),
("Expert parallelism","Placing MoE experts on different GPUs."),
("FlashAttention","IO-aware exact attention kernel that avoids materializing the score matrix in HBM."),
("FP8","8-bit floating point format with hardware support on Hopper and newer GPUs."),
("FSDP","Fully Sharded Data Parallel: shards parameters, gradients and optimizer state."),
("Gang scheduling","Starting all pods of a distributed job together or not at all."),
("GGUF","llama.cpp file format for quantized models."),
("Golden set","Curated labeled examples used to evaluate quality over time."),
("Goodput","Throughput counting only requests that met their SLOs."),
("GPU Operator","NVIDIA Kubernetes operator managing drivers, toolkit, device plugin, DCGM and MIG."),
("GPUDirect RDMA","Lets NICs read and write GPU memory directly, bypassing the CPU."),
("GQA","Grouped-query attention: several query heads share key/value heads."),
("GraphRAG","RAG over an LLM-extracted knowledge graph with community summaries."),
("GRPO","Group Relative Policy Optimization: RL using group-relative rewards, common with verifiable tasks."),
("Guardrails","Checks on model inputs and outputs enforcing safety and policy."),
("Harness","Everything around the model in an agent: loop, tools, middleware, memory, traces."),
("HBM","High-bandwidth memory stacked next to the GPU die."),
("Hedging","Sending a backup request when the first is slow to cut tail latency."),
("HNSW","Hierarchical Navigable Small World graph index for ANN search."),
("HyDE","Hypothetical Document Embeddings: search using a generated hypothetical answer."),
("Idempotency key","Token ensuring a retried operation takes effect only once."),
("InfiniBand","Low-latency, lossless RDMA network fabric common in AI clusters."),
("Indirect prompt injection","Malicious instructions hidden in content the model reads, not typed by the user."),
("ITL / TBT","Inter-token latency / time between tokens during streaming."),
("IVF","Inverted file index: clusters vectors and searches the nearest lists."),
("KL divergence","Measure of how one probability distribution differs from another."),
("Kueue","Kubernetes job queueing with quotas, borrowing and fair sharing."),
("KV cache","Stored keys and values of past tokens so decode avoids recomputation."),
("Lethal trifecta","Untrusted input + private data + outbound channel: the recipe for exfiltration."),
("LLM gateway","Proxy giving one API with keys, budgets, routing, fallbacks and traces."),
("LLM-as-judge","Using a model to grade outputs against a rubric."),
("LoRA","Low-Rank Adaptation: fine-tuning small low-rank matrices on a frozen base."),
("Lost in the middle","Models recall information at context edges better than in the middle."),
("MCP","Model Context Protocol connecting AI hosts to tools, resources and prompts."),
("MIG","Multi-Instance GPU: hardware partitions with isolated SMs and memory."),
("MLA","Multi-head latent attention: compresses KV into a smaller latent."),
("MoE","Mixture of Experts: router sends each token to a few expert networks."),
("MPS","CUDA Multi-Process Service: concurrent kernels from multiple processes."),
("MQA","Multi-query attention: all query heads share one KV head."),
("NCCL","NVIDIA Collective Communications Library for multi-GPU collectives."),
("NIXL","NVIDIA Inference Xfer Library for moving KV cache between workers."),
("NVLink","High-bandwidth GPU-to-GPU interconnect."),
("NVSwitch","Switch chip connecting many GPUs over NVLink at full bandwidth."),
("P/D disaggregation","Running prefill and decode on separate GPU pools."),
("PagedAttention","KV cache in fixed-size blocks like virtual memory pages."),
("Pipeline parallelism","Splitting model layers into stages on different GPUs."),
("Prefill","Processing the whole prompt in parallel; compute-bound; sets TTFT."),
("Prefix caching","Reusing KV for identical prompt prefixes across requests."),
("Product quantization","Compressing vectors into short codes by quantizing sub-vectors."),
("PUE","Power usage effectiveness: facility power divided by IT power."),
("QLoRA","LoRA trained on a 4-bit quantized base model."),
("RadixAttention","SGLang's tree-structured automatic prefix cache."),
("RAG","Retrieval-augmented generation: ground answers in retrieved documents."),
("RDMA","Remote direct memory access between machines without CPU involvement."),
("Reranker","Model that reorders retrieved candidates by relevance."),
("Reward hacking","A model exploiting loopholes in a reward instead of solving the task."),
("RLHF","Reinforcement learning from human feedback via a reward model."),
("RoCE","RDMA over Converged Ethernet."),
("RoPE","Rotary position embedding: encodes position by rotating q/k vector pairs."),
("Row remapping","GPU replacing faulty memory rows; takes effect after reset."),
("safetensors","Safe, memory-mappable tensor file format that cannot execute code."),
("Semantic cache","Cache returning stored answers for semantically similar prompts."),
("SFT","Supervised fine-tuning on input-output examples."),
("SLO","Service level objective, e.g. p95 TTFT under 800 ms."),
("Speculative decoding","Draft tokens cheaply, verify them in one target-model pass."),
("Straggler","A slow rank holding back a synchronous distributed job."),
("Structured output","Constraining generation to a schema or grammar."),
("Temperature","Sampling parameter scaling logits; lower is more deterministic."),
("Tensor parallelism","Splitting each layer's matrices across GPUs."),
("Time-slicing","Sharing one GPU across processes by context switching, no isolation."),
("Token fertility","Average tokens per word for a language or domain."),
("Top-p","Nucleus sampling: sample from the smallest set whose probability sums to p."),
("TTFT","Time to first token."),
("vLLM","Open-source LLM serving engine with PagedAttention and continuous batching."),
("Volcano","Kubernetes batch scheduler with gang scheduling and queues."),
("Xid","NVIDIA driver error code in the kernel log indicating a GPU fault."),
("YaRN","RoPE scaling method for extending context length."),
("ZeRO","DeepSpeed's optimizer-state, gradient and parameter sharding."),
]
